            const val = parseFloat(e.target.value);
            weightValue.textContent = val.toFixed(2);
            processImages();
        });

        // Main Logic: Process Images
        function processImages() {
            if (!leftLoaded || !rightLoaded) {
                // If either is missing, clear the middle result
                imgMiddle.style.display = 'none';
                return;
            }

            const w = parseFloat(weightSlider.value); // Weight for Left
            const w2 = 1 - w; // Weight for Right

            // Get Canvas to manipulate pixels
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');

            // Set canvas size to match the images (assuming same dimensions)
            canvas.width = imgLeft.naturalWidth;
            canvas.height = imgLeft.naturalHeight;

            // Draw images onto canvas
            ctx.drawImage(imgLeft, 0, 0);
            ctx.drawImage(imgRight, 0, 0);

            // Get pixel data
            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = imageData.data;

            // Loop through pixels and apply weighted average
            // We iterate by 4 (RGBA)
            for (let i = 0; i < data.length; i += 4) {
                const r = data[i];
                const g = data[i + 1];
                const b = data[i + 2];
                const a = data[i + 3];

                // Calculate weighted average for RGB
                const newR = Math.round(r * w + data[i] * w2); // data[i] is right image red
                const newG = Math.round(g * w + data[i + 1] * w2);
                const newB = Math.round(b * w + data[i + 2] * w2);

                // Alpha channel: Simple average of transparency
                const newA = Math.round(a * w + data[i + 3] * w2);

                // Set new pixel
                data[i] = newR;
                data[i + 1] = newG;
                data[i + 2] = newB;
                data[i + 3] = newA;
            }

            // Put data back and update the middle image
            ctx.putImageData(imageData, 0, 0);

            // Convert canvas to image URL
            imgMiddle.src = canvas.toDataURL('image/png');
            imgMiddle.style.display = 'block';
        }
    </script>
