                        'Content-Type': 'application/x-www-form-urlencoded'
                    },
                    body: formData
                });

                if (!response.ok) {
                    const errData = await response.json();
                    throw new Error(errData.message || 'Failed to generate image');
                }

                // 5. Handle Response (Example for Stability AI)
                // The response is usually a JSON object containing an 'output' URL
                const data = await response.json();

                // Assuming the API returns an object with an 'output' property containing the image URL
                // You may need to adjust this line based on your specific API documentation
                const imageUrl = data.output; 

                // 6. Display Image
                img.src = imageUrl;
                img.onload = () => {
                    img.style.display = "block";
                    loading.style.display = "none";
                    btn.disabled = false;
                    btn.innerText = "Generate Image";
                };

            } catch (error) {
                console.error(error);
                errorDiv.innerText = "Error: " + error.message;
                errorDiv.style.display = "block";
                loading.style.display = "none";
                btn.disabled = false;
                btn.innerText = "Generate Image";
            }
        }
    </script>
</body>
</html>
