// MARK: - Reusable Credit Card Field
struct CreditCardField: View {
    let label: String
    let placeholder: String
    @Binding var value: String
    let keyboardType: UIKeyboardType
    let maxLength: Int
    @Binding var isSave: Bool

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
