                            if cleaned.count <= maxLength {
                                value = cleaned
                            } else {
                                value = cleaned.prefix(maxLength)
                            }
                        }
                    }
                    .onAppear {
                        // Trigger autocomplete on first tap
                        if !value.isEmpty {
                            // Optional: Add specific modifiers if needed for specific fields
                        }
                    }
            }
        }
    }
}

